def solve(rows, cols, r, c):
    neighbors = []
    if r > 0:
        neighbors.append([r - 1, c])
    if r < rows - 1:
        neighbors.append([r + 1, c])
    if c > 0:
        neighbors.append([r, c - 1])
    if c < cols - 1:
        neighbors.append([r, c + 1])
    return sorted(neighbors)

